import React, { useState, useEffect, useCallback, useRef } from 'react';
import { motion, AnimatePresence } from 'framer-motion';
import clsx from 'clsx';
import './AcidCarousel.css';

export interface AcidCarouselItem {
    id: string;
    title: string;
    label?: string;
    description: string;
    content?: React.ReactNode;
}

export interface AcidCarouselProps {
    items: AcidCarouselItem[];
    direction?: 'horizontal' | 'vertical';
    autoPlay?: boolean;
    interval?: number;
    className?: string;
}

export const AcidCarousel = ({
    items,
    direction = 'horizontal',
    autoPlay = false,
    interval = 5000,
    className
}: AcidCarouselProps) => {
    const [activeIndex, setActiveIndex] = useState(0);
    const [progress, setProgress] = useState(0);
    const progressRef = useRef(0);
    const lastTimeRef = useRef(0);
    const requestRef = useRef<number | undefined>(undefined);

    const nextSlide = useCallback(() => {
        setActiveIndex((prev) => (prev + 1) % items.length);
        setProgress(0);
        progressRef.current = 0;
    }, [items.length]);

    const selectSlide = (index: number) => {
        setActiveIndex(index);
        setProgress(0);
        progressRef.current = 0;
    };

    const animate = useCallback((time: number) => {
        if (!autoPlay) return;

        if (lastTimeRef.current !== undefined) {
            const deltaTime = time - lastTimeRef.current;
            progressRef.current += (deltaTime / interval) * 100;

            if (progressRef.current >= 100) {
                nextSlide();
            } else {
                setProgress(progressRef.current);
            }
        }

        lastTimeRef.current = time;
        requestRef.current = requestAnimationFrame(animate);
    }, [autoPlay, interval, nextSlide]);

    useEffect(() => {
        if (autoPlay) {
            requestRef.current = requestAnimationFrame(animate);
            return () => {
                if (requestRef.current) cancelAnimationFrame(requestRef.current);
            };
        } else {
            setProgress(0);
            progressRef.current = 0;
        }
    }, [autoPlay, animate]);

    // Asterisk icon to match the aesthetic
    const Asterisk = ({ active }: { active: boolean }) => (
        <motion.div
            className={clsx('ac-asterisk', active && 'active')}
            animate={{ rotate: active ? 180 : 0 }}
            transition={{ duration: 0.8, ease: "easeInOut" }}
        >
            <svg width="24" height="24" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2" strokeLinecap="round" strokeLinejoin="round">
                <path d="M12 2v20M17 5L7 19M22 12H2M19 17L5 7" />
            </svg>
        </motion.div>
    );

    return (
        <div className={clsx('ac-carousel-container', `ac-${direction}`, className)}>
            <div className="ac-carousel-controls">
                {items.map((item, idx) => {
                    const isActive = idx === activeIndex;
                    return (
                        <button
                            key={item.id}
                            className={clsx('ac-carousel-tab', isActive && 'active')}
                            onClick={() => selectSlide(idx)}
                        >
                            <div className="ac-tab-header">
                                <div className="ac-tab-indicator">
                                    <Asterisk active={isActive} />
                                </div>
                                <div className="ac-tab-title-group">
                                    {item.label && <span className="ac-tab-label">{item.label}</span>}
                                    <h3 className="ac-tab-title">{item.title}</h3>
                                </div>
                            </div>

                            <AnimatePresence>
                                {isActive && (
                                    <motion.div
                                        initial={{ height: 0, opacity: 0 }}
                                        animate={{ height: 'auto', opacity: 1 }}
                                        exit={{ height: 0, opacity: 0 }}
                                        className="ac-tab-content"
                                    >
                                        <p>{item.description}</p>
                                    </motion.div>
                                )}
                            </AnimatePresence>

                            {/* Progress Bar for Autoplay */}
                            {autoPlay && (
                                <div className="ac-tab-progress-bg">
                                    <motion.div
                                        className="ac-tab-progress-fill"
                                        initial={{ width: '0%' }}
                                        animate={{ width: isActive ? `${progress}%` : (idx < activeIndex ? '100%' : '0%') }}
                                        transition={{ duration: 0 }}
                                    />
                                </div>
                            )}
                        </button>
                    );
                })}
            </div>

            <div className="ac-carousel-display">
                <AnimatePresence mode="popLayout">
                    <motion.div
                        key={activeIndex}
                        initial={{ opacity: 0, scale: 0.96, filter: 'blur(10px)' }}
                        animate={{ opacity: 1, scale: 1, filter: 'blur(0px)' }}
                        exit={{ opacity: 0, scale: 1.04, filter: 'blur(10px)' }}
                        transition={{ duration: 0.6, ease: [0.16, 1, 0.3, 1] }}
                        className="ac-carousel-visual"
                    >
                        {items[activeIndex].content || (
                            <div className="ac-carousel-placeholder">
                                <motion.div
                                    animate={{ rotate: 360 }}
                                    transition={{ duration: 20, repeat: Infinity, ease: "linear" }}
                                >
                                    <svg width="64" height="64" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="1" strokeLinecap="round" strokeLinejoin="round" style={{ opacity: 0.2 }}>
                                        <path d="M12 2v20M17 5L7 19M22 12H2M19 17L5 7" />
                                    </svg>
                                </motion.div>
                                <span>{items[activeIndex].title} VISUAL_MODULE</span>
                            </div>
                        )}
                    </motion.div>
                </AnimatePresence>
            </div>
        </div>
    );
};

.ac-carousel-container {
    display: flex;
    gap: 2rem;
    width: 100%;
    color: var(--ac-text);
}

.ac-carousel-container.ac-vertical {
    flex-direction: row;
}

.ac-carousel-container.ac-horizontal {
    flex-direction: column;
}

.ac-carousel-controls {
    display: flex;
    gap: 1rem;
    flex: 1;
}

.ac-carousel-container.ac-vertical .ac-carousel-controls {
    flex-direction: column;
    min-width: 300px;
    max-width: 400px;
}

.ac-carousel-container.ac-horizontal .ac-carousel-controls {
    flex-direction: row;
}

.ac-carousel-tab {
    display: flex;
    flex-direction: column;
    text-align: left;
    background: transparent;
    border: none;
    padding: 1.5rem 0;
    cursor: pointer;
    border-bottom: 1px solid var(--ac-border);
    position: relative;
    opacity: 0.5;
    transition: all 0.3s ease;
}

.ac-carousel-tab.active {
    opacity: 1;
}

.ac-carousel-tab:hover {
    opacity: 0.8;
}

.ac-tab-header {
    display: flex;
    align-items: center;
    gap: 1rem;
}

.ac-asterisk {
    color: var(--ac-text-muted);
}

.ac-asterisk.active {
    color: var(--ac-brand);
}

.ac-tab-title-group {
    display: flex;
    flex-direction: column;
}

.ac-tab-label {
    font-size: 0.65rem;
    font-family: 'JetBrains Mono', monospace;
    letter-spacing: 0.1em;
    color: var(--ac-brand);
    margin-bottom: 0.25rem;
}

.ac-tab-title {
    font-size: 1.25rem;
    font-weight: 700;
    margin: 0;
    letter-spacing: -0.02em;
}

.ac-tab-content {
    overflow: hidden;
    padding-left: 2.5rem;
    /* align with text, bypassing asterisk */
}

.ac-tab-content p {
    font-size: 0.9rem;
    color: var(--ac-text-muted);
    margin: 1rem 0 0 0;
    line-height: 1.6;
}

.ac-tab-progress-bg {
    position: absolute;
    bottom: -1px;
    /* Overlap border */
    left: 0;
    width: 100%;
    height: 2px;
    background: transparent;
    overflow: hidden;
}

.ac-tab-progress-fill {
    height: 100%;
    background: var(--ac-brand);
}

/* Display Area */
.ac-carousel-display {
    flex: 2;
    position: relative;
    min-height: 400px;
    border-radius: 12px;
    background: var(--ac-surface);
    border: 1px solid var(--ac-border);
    overflow: hidden;
    display: flex;
    align-items: center;
    justify-content: center;
}

.ac-carousel-container.ac-horizontal .ac-carousel-display {
    width: 100%;
    min-height: 500px;
}

.ac-carousel-visual {
    width: 100%;
    height: 100%;
    position: absolute;
    top: 0;
    left: 0;
}

.ac-carousel-placeholder {
    width: 100%;
    height: 100%;
    display: flex;
    flex-direction: column;
    align-items: center;
    justify-content: center;
    gap: 1rem;
    font-family: 'JetBrains Mono', monospace;
    font-size: 0.75rem;
    color: var(--ac-text-muted);
    letter-spacing: 0.1em;
}

@media (max-width: 768px) {
    .ac-carousel-container.ac-vertical {
        flex-direction: column;
    }

    .ac-carousel-controls {
        max-width: 100%;
    }
}
